        perror(filename);
        exit(EXIT_FAILURE);
    }
    char line[52];   // 50 chars + '\n' + '\0'
    for (int i = 0; i < 5; i++) {
        if (fgets(line, sizeof(line), f) == NULL) {
            fprintf(stderr, "error: %s has fewer than 5 lines\n", filename);
            fclose(f);
            exit(EXIT_FAILURE);
        }
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[len - 1] = '\0';
            len--;
        }
        if (len < 2) {
            fprintf(stderr, "error: line %d of %s has fewer than 2 characters\n",
                    i + 1, filename);
            fclose(f);
            exit(EXIT_FAILURE);
        }
        structArray[i].firstChar = line[0];
        structArray[i].lastChar = line[len - 1];
    }
    fclose(f);
}
